//! Compares the Rust font layer with LÖVE 11.5's own numbers for the bundled fonts
//! (`tests/fixtures/love_fonts.txt`, regenerated by `tools/lua_golden/fonts/run.sh`): line
//! height, ascent, baseline, text widths, wrapping and glyph metrics at many sizes and scales.

use std::path::PathBuf;

use gametable::graphics::text::{FontFace, FontKey, FontLibrary};

fn face_for(file: &str) -> FontFace {
    match file {
        "Roboto-Regular.ttf" => FontFace::Regular,
        "Roboto-Medium.ttf" => FontFace::Medium,
        "Roboto-Bold.ttf" => FontFace::Bold,
        "MaterialIcons-Regular.ttf" => FontFace::Icons,
        "NotoSansSymbols2-Regular.ttf" => FontFace::Symbols,
        other => panic!("unknown font {other}"),
    }
}

const SAMPLES: [&str; 5] = [
    "Hello, World!",
    "CardTable",
    "The quick brown fox jumps over the lazy dog",
    "Ace of Spades \u{2660}",
    "iiiWWW 0123456789",
];
const WRAP_TEXT: &str = "The quick brown fox jumps over the lazy dog and keeps running far away";

fn field<'a>(line: &'a str, name: &str) -> &'a str {
    let start = line.find(&format!(" {name}=")).unwrap_or_else(|| panic!("{name} missing in {line}")) + name.len() + 2;
    let rest = &line[start..];
    let end = rest.find(" wraps=").filter(|_| name != "wraps").unwrap_or(rest.len());
    let end = rest[..end].find(' ').filter(|_| name != "wraps").unwrap_or(end);
    &rest[..end]
}

#[test]
fn matches_love_font_metrics() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let golden = std::fs::read_to_string(root.join("tests/fixtures/love_fonts.txt")).unwrap();
    let mut fonts = FontLibrary::new(&root.join("../../assets/fonts")).unwrap();
    let mut checked = 0;
    let mut mismatches = Vec::new();
    for line in golden.lines() {
        let parts: Vec<&str> = line.splitn(5, ' ').collect();
        let (kind, file, size, scale) = (parts[0], parts[1], parts[2], parts[3]);
        let key = FontKey::new(face_for(file), size.parse().unwrap());
        fonts.set_dpi_scale(scale.parse().unwrap());
        let label = format!("{file} {size} @{scale}");
        match kind {
            "F" => {
                let metrics = fonts.line_metrics(key);
                let expected_height: f32 = field(line, "height").parse().unwrap();
                let expected_ascent: f32 = field(line, "ascent").parse().unwrap();
                let expected_baseline: f32 = field(line, "baseline").parse().unwrap();
                if (metrics.height, metrics.ascent, metrics.baseline())
                    != (expected_height, expected_ascent, expected_baseline)
                {
                    mismatches.push(format!(
                        "{label}: height/ascent/baseline {:?} vs LÖVE {:?}",
                        (metrics.height, metrics.ascent, metrics.baseline()),
                        (expected_height, expected_ascent, expected_baseline)
                    ));
                }
                let expected_widths: Vec<f32> = field(line, "widths").split(',').map(|w| w.parse().unwrap()).collect();
                for (sample, expected) in SAMPLES.iter().zip(expected_widths) {
                    let width = fonts.width(key, sample);
                    if width != expected {
                        mismatches.push(format!("{label}: width of {sample:?} {width} vs LÖVE {expected}"));
                    }
                }
                for (limit, expected) in [60.0, 120.0, 200.0].iter().zip(field(line, "wraps").split('#')) {
                    let (widest, lines) = fonts.wrap(key, WRAP_TEXT, *limit);
                    let texts: Vec<String> = lines.into_iter().map(|line| line.text).collect();
                    let actual = format!("{widest}:{}:{}", texts.len(), texts.join("|"));
                    if actual != expected {
                        mismatches.push(format!("{label}: wrap at {limit}\n  rust {actual}\n  löve {expected}"));
                    }
                }
                checked += 1;
            }
            "G" => {
                let character = parts[4][1..].split('"').next().unwrap().chars().next().unwrap();
                let expected: Vec<i32> =
                    ["adv", "bx", "by", "w", "h"].iter().map(|name| field(line, name).parse().unwrap()).collect();
                let (advance, bearing_x, bearing_y, width, height) = fonts.glyph_data(key, character);
                let actual = vec![advance, bearing_x, bearing_y, width as i32, height as i32];
                if actual != expected {
                    mismatches.push(format!(
                        "{label}: glyph {character:?} [adv, bx, by, w, h] {actual:?} vs LÖVE {expected:?}"
                    ));
                }
            }
            _ => panic!("unexpected line {line}"),
        }
    }
    assert!(checked >= 300, "only {checked} cases checked");
    assert!(mismatches.is_empty(), "{} mismatches:\n{}", mismatches.len(), mismatches.join("\n"));
}
